function filterWorkshops(sessions, criteria) {
	const normalizedQuery = criteria.searchQuery.trim().toLowerCase();
	return sessions.filter((session) => {
		if (criteria.onlySaved && !criteria.savedIds.includes(session.id)) return false;
		if (criteria.day !== "All Days" && session.day !== criteria.day) return false;
		if (criteria.track !== "All Tracks" && session.track !== criteria.track) return false;
		if (normalizedQuery.length > 0) {
			if (![
				session.title,
				session.speakerName,
				session.organization,
				session.description,
				session.hall,
				session.track,
				...session.keyTakeaways
			].join(" ").toLowerCase().includes(normalizedQuery)) return false;
		}
		return true;
	});
}
function toggleSavedWorkshop(savedIds, sessionId) {
	if (!sessionId.trim()) return savedIds;
	if (savedIds.includes(sessionId)) return savedIds.filter((id) => id !== sessionId);
	return [...savedIds, sessionId];
}
function getRemainingSeats(session, isSavedByUser) {
	const effectiveRegistered = session.registeredCount + (isSavedByUser ? 1 : 0);
	return Math.max(0, session.capacity - effectiveRegistered);
}
function validateEmail(email) {
	const trimmed = email.trim();
	if (!trimmed) return {
		valid: false,
		error: "Please enter your email address."
	};
	if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) return {
		valid: false,
		error: "Please enter a valid work or personal email address."
	};
	return { valid: true };
}
function validateAttendeeRegistration(input) {
	const errors = {};
	if (!input.fullName || input.fullName.trim().length < 2) errors.fullName = "Full name is required (at least 2 characters).";
	const emailCheck = validateEmail(input.email);
	if (!emailCheck.valid) errors.email = emailCheck.error;
	if (!input.organization || input.organization.trim().length < 2) errors.organization = "Company or organization name is required.";
	if (!input.primaryInterest || !input.primaryInterest.trim()) errors.primaryInterest = "Please select a primary manufacturing or sourcing interest.";
	return {
		valid: Object.keys(errors).length === 0,
		errors
	};
}
function generateBadgeCode(email, attendeeType) {
	const cleanEmail = email.trim().toLowerCase();
	let hash = 0;
	for (let i = 0; i < cleanEmail.length; i++) hash = (hash * 31 + cleanEmail.charCodeAt(i)) % 1e4;
	return `SUBCON27-${attendeeType.startsWith("Buyer") ? "BYR" : attendeeType.startsWith("MSME") ? "MFG" : "VIS"}-${String(hash).padStart(4, "0")}`;
}
